def _parse_dots_puzzles(raw):
    import re
    puzzles = []
    for section in re.split(r"\n\s*\n", raw.strip()):
        groups = []
        for line in section.splitlines():
            category, words = line.split(" :: ", 1)
            groups.append((category.strip(), [x.strip().upper() for x in words.split("|")]))
        puzzles.append(groups)
    return puzzles


DOTS_PUZZLES = _parse_dots_puzzles(DOTS_PUZZLES_TEXT)

