def validate_content():
    assert len(CLUELESS_WORDS) >= 350, "Too few Clueless cards"
    assert len(CLUELESS_WORDS) == len(set(CLUELESS_WORDS)), "Duplicate Clueless card"
    assert all(len(w) <= 24 for w in CLUELESS_WORDS), "Clueless phrase too long for phones"
    assert len(CLUELESS_EXTREME_WORDS) >= 150, "Too few Extreme Clueless cards"
    assert len(CLUELESS_EXTREME_WORDS) == len(set(CLUELESS_EXTREME_WORDS)), "Duplicate Extreme Clueless card"
    assert all(len(word) <= 24 for word in CLUELESS_EXTREME_WORDS), "Extreme Clueless phrase too long for phones"
    assert len(DOTS_PUZZLES) >= 40, "Too few Connections puzzles"
    for board in DOTS_PUZZLES:
        assert len(board) == 4, "Connections board must have 4 groups"
        assert all(len(words) == 4 for _, words in board), "Connections group must have 4 words"
        assert len({word for _, group in board for word in group}) == 16, "Duplicate word within board"
        assert all(len(word) <= 24 for _, group in board for word in group), "Connections word too long for phones"
    assert all(len(card["forbidden"]) == 5 and card["target"] not in card["forbidden"] for card in FORBIDDEN_CARDS)
    assert len({c["target"] for c in FORBIDDEN_CARDS}) == len(FORBIDDEN_CARDS)


validate_content()
